"""Build a self-contained Kaggle kernel script from a template, plus its kernel-metadata.json, from a JSON config.

Usage (repo root):
    .venv/Scripts/python.exe -I -B src/tools/build_kernel.py <config.json> [--out-dir DIR] [--check]

  --out-dir  write the script and metadata into DIR instead of the paths in the config
  --check    write nothing; compare the generated bytes with the existing files (working tree, and the git HEAD
             blob when the file is tracked) and exit 1 if neither matches

The template is ordinary Python with placeholders (e.g. __SOURCES_JSON__). Each placeholder is replaced in one
pass over the template, so text inserted for one placeholder is never scanned for another. A template placeholder
(an all-caps __NAME__) without a substitution in the config is an error. The tool never pushes; run
`kaggle kernels push -p <kernel dir>` yourself after reading the script.

Config keys (paths relative to the repo root unless absolute):
  template          template path (optional: without it only kernel-metadata.json is written, for a
                    hand-written script such as exp-001's)
  script            output script path; its file name becomes metadata code_file
  substitutions     {placeholder: spec}. Each spec has one value source:
                      {"text": "..."}                      literal string
                      {"value": <any JSON>}                literal JSON value
                      {"file_text": path}                  file text (universal newlines -> LF)
                      {"json_file": path}                  parsed JSON
                      {"sources": dir, "pattern": "*.py", "recursive": false, "prefix": "pkg/"}
                                                           {prefix + relative posix path: text} sorted by path
                      {"file_b64": path, "sha256": hex}    base64 of a binary file; sha256 checked if given
                      {"zip_b64": dir, "prefix": "pkg/"}  deterministic zip of every file under dir (no
                                                           __pycache__), base64; "sort": "posix" (default,
                                                           case-sensitive path order) or "windows"
                      {"zip_members": dir, "prefix": ...}  {member name: sha256} of that same zip
                    optional on every spec:
                      "git_commit": "<rev>"   read files from that commit (git show / ls-tree) instead of the
                                              working tree; recommended, the worktree may carry CRLF
                                              (core.autocrlf) or uncommitted edits
                      "encode": "raw" | "repr" | "json"   how the value becomes text (default: raw for strings,
                                              repr otherwise); "json_kwargs": {...} for encode json
                      "count": N | "any"      required occurrences in the template (default 1)
  metadata          kernel-metadata.json fields; "id" is required. Defaults: title = id after "/", code_file =
                    script name, language python, kernel_type script, is_private true, enable_gpu false,
                    enable_tpu false, enable_internet true, dataset_sources [], competition_sources
                    [google-verifiable-quantum-circuit-compilation], kernel_sources [], model_sources [].
  metadata_path     default: kernel-metadata.json next to the script
  metadata_indent   default 1

Behaviour chosen where the per-experiment copies diverged (exp-003/005 kernel/build_kernel.py, exp-006/008/009
make_kernel.py, exp-011 kernel/make_kernel.py); the latest wins:
  - Exactly one occurrence per placeholder by default (exp-003, exp-005, exp-011 asserted it). exp-009 replaced
    every occurrence of __SALT__ (2 in its template); its config says "count": 2.
  - One-pass substitution. The copies called str.replace in sequence, which would also have replaced a placeholder
    appearing inside inserted text; for exp-009 the outputs are the same.
  - Script written with LF line ends (exp-006, 008, 009, 011). exp-003/005 used write_text without newline=, which
    gives CRLF on Windows.
  - kernel-metadata.json: written with LF and indent 1, no trailing newline (exp-009's json.dumps(meta, indent=1));
    exp-009's working-tree copy has CRLF (write_text on Windows) while git stores LF. exp-011's metadata was
    hand-written (indent 2, inline lists), not generated.
  - Sources: exp-009 read src/invsqrt from git at a commit (git show), exp-008 from the working tree; both are
    supported ("git_commit"). Zip of a source tree: exp-011's parameters (ZIP_DEFLATED level 9, date 1980-01-01,
    create_system 3, mode 0o100644). exp-011 sorted Path objects on Windows, which is case-insensitive per part
    (generate.py before LICENSE) and so platform-dependent; the default here is case-sensitive posix order, and
    "sort": "windows" reproduces exp-011's zip.
"""
from __future__ import annotations

import argparse
import base64
import fnmatch
import hashlib
import io
import json
import re
import subprocess
import sys
import zipfile
from pathlib import Path, PurePosixPath

REPO = Path(__file__).resolve().parents[2]
META_DEFAULTS = {'language': 'python', 'kernel_type': 'script', 'is_private': True, 'enable_gpu': False,
                 'enable_tpu': False, 'enable_internet': True, 'dataset_sources': [],
                 'competition_sources': ['google-verifiable-quantum-circuit-compilation'], 'kernel_sources': [],
                 'model_sources': []}
META_ORDER = ['id', 'title', 'code_file', 'language', 'kernel_type', 'is_private', 'enable_gpu', 'enable_tpu',
              'enable_internet', 'dataset_sources', 'competition_sources', 'kernel_sources', 'model_sources']
SOURCES = ('text', 'value', 'file_text', 'json_file', 'sources', 'file_b64', 'zip_b64', 'zip_members')
SPEC_KEYS = set(SOURCES) | {'git_commit', 'encode', 'json_kwargs', 'count', 'pattern', 'recursive', 'prefix',
                            'sha256', 'sort'}
PLACEHOLDER = re.compile(r'__[A-Z][A-Z0-9_]*__')


def rpath(p) -> Path:
    p = Path(p)
    return p if p.is_absolute() else REPO / p


def rel(p) -> str:
    """Repo-relative posix path (for git)."""
    p = rpath(p).resolve()
    return p.relative_to(REPO.resolve()).as_posix()


def git(*args) -> bytes:
    return subprocess.run(['git', '-C', str(REPO), *args], check=True, capture_output=True).stdout


def read_bytes(path, commit):
    return git('show', f'{commit}:{rel(path)}') if commit else rpath(path).read_bytes()


def read_text(path, commit):
    b = read_bytes(path, commit).decode('utf-8')
    return b.replace('\r\n', '\n').replace('\r', '\n')  # universal newlines, as Path.read_text


def list_files(d, commit, recursive=True):
    """Repo-relative posix paths of the files under d, sorted."""
    base = rel(d).rstrip('/') + '/'
    if commit:
        names = git('ls-tree', '-r', '--name-only', commit, base).decode('utf-8').split('\n')
        names = [n for n in names if n and (recursive or '/' not in n[len(base):])]
    else:
        root = rpath(d)
        it = root.rglob('*') if recursive else root.glob('*')
        names = [rel(p) for p in it if p.is_file()]
    return sorted(n for n in names if '__pycache__' not in PurePosixPath(n).parts)


def make_zip(spec, commit):
    """exp-011's deterministic zip: sorted members, fixed metadata. Returns (bytes, {name: sha256})."""
    d = spec.get('zip_b64') or spec.get('zip_members')
    base = rel(d).rstrip('/') + '/'
    buf = io.BytesIO()
    members = {}
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as z:
        names = list_files(d, commit)
        if spec.get('sort', 'posix') == 'windows':  # WindowsPath order: case-insensitive, part by part (exp-011)
            names.sort(key=lambda n: [x.lower() for x in PurePosixPath(n).parts])
        for n in names:
            name = spec.get('prefix', '') + n[len(base):]
            data = read_bytes(n, commit)
            zi = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
            zi.create_system = 3
            zi.external_attr = 0o100644 << 16
            zi.compress_type = zipfile.ZIP_DEFLATED
            z.writestr(zi, data)
            members[name] = hashlib.sha256(data).hexdigest()
    return buf.getvalue(), members


def value_of(key, spec, info):
    kinds = [k for k in SOURCES if k in spec]
    bad = [k for k in spec if k not in SPEC_KEYS]
    if len(kinds) != 1 or bad:
        raise ValueError(f'{key}: need exactly one of {SOURCES}; unknown keys {bad}')
    kind, commit = kinds[0], spec.get('git_commit')
    if kind == 'text':
        return spec['text']
    if kind == 'value':
        return spec['value']
    if kind == 'file_text':
        return read_text(spec['file_text'], commit)
    if kind == 'json_file':
        return json.loads(read_text(spec['json_file'], commit))
    if kind == 'sources':
        d = spec['sources']
        base = rel(d).rstrip('/') + '/'
        pat = spec.get('pattern', '*')
        out = {}
        for n in list_files(d, commit, spec.get('recursive', False)):
            r = n[len(base):]
            if fnmatch.fnmatchcase(PurePosixPath(r).name, pat) or fnmatch.fnmatchcase(r, pat):
                out[spec.get('prefix', '') + r] = read_text(n, commit)
        info['files'] = {k: hashlib.sha256(v.encode('utf-8')).hexdigest()[:12] for k, v in out.items()}
        return out
    if kind == 'file_b64':
        raw = read_bytes(spec['file_b64'], commit)
        h = hashlib.sha256(raw).hexdigest()
        if 'sha256' in spec and h != spec['sha256']:
            raise ValueError(f"{key}: {spec['file_b64']} has SHA-256 {h}, config expects {spec['sha256']}")
        info |= {'file_sha256': h, 'file_bytes': len(raw)}
        return base64.b64encode(raw).decode('ascii')
    raw, members = make_zip(spec, commit)
    info |= {'zip_sha256': hashlib.sha256(raw).hexdigest(), 'zip_bytes': len(raw), 'members': len(members)}
    return base64.b64encode(raw).decode('ascii') if kind == 'zip_b64' else members


def encode(key, spec, v):
    enc = spec.get('encode', 'raw' if isinstance(v, str) else 'repr')
    if enc == 'raw':
        if not isinstance(v, str):
            raise ValueError(f'{key}: encode raw needs a string value')
        return v
    if enc == 'repr':
        return repr(v)
    if enc == 'json':
        return json.dumps(v, **spec.get('json_kwargs', {}))
    raise ValueError(f'{key}: encode {enc!r}')


def build(cfg):
    """Returns ({path: bytes}, report)."""
    script = rpath(cfg['script'])
    files, report = {}, {'substitutions': {}}
    if 'template' in cfg:
        tpl = read_text(cfg['template'], None)
        subs = cfg.get('substitutions', {})
        missing = sorted(set(PLACEHOLDER.findall(tpl)) - set(subs))
        if missing:
            raise ValueError(f'template placeholders without a substitution: {missing}')
        texts = {}
        for key, spec in subs.items():
            n, want = tpl.count(key), spec.get('count', 1)
            if (want == 'any' and n == 0) or (want != 'any' and n != want):
                raise ValueError(f'{key}: {n} occurrences in the template, config expects {want}')
            info = {'occurrences': n}
            texts[key] = encode(key, spec, value_of(key, spec, info))
            info |= {'inserted_bytes': len(texts[key].encode('utf-8')),
                     'inserted_sha256': hashlib.sha256(texts[key].encode('utf-8')).hexdigest()}
            report['substitutions'][key] = info
        pat = re.compile('|'.join(re.escape(k) for k in sorted(texts, key=len, reverse=True)))
        out = pat.sub(lambda m: texts[m.group(0)], tpl) if texts else tpl
        files[script] = out.encode('utf-8')
    elif cfg.get('substitutions'):
        raise ValueError('substitutions given without a template')
    meta = dict(META_DEFAULTS) | cfg['metadata']
    meta.setdefault('title', meta['id'].split('/', 1)[1])
    meta.setdefault('code_file', script.name)
    meta = {k: meta[k] for k in META_ORDER if k in meta} | {k: v for k, v in meta.items() if k not in META_ORDER}
    mpath = rpath(cfg['metadata_path']) if 'metadata_path' in cfg else script.parent / 'kernel-metadata.json'
    files[mpath] = json.dumps(meta, indent=cfg.get('metadata_indent', 1)).encode('utf-8')
    return files, report


def check(files):
    res, ok = {}, True
    for p, data in files.items():
        r = {'new_sha256': hashlib.sha256(data).hexdigest(), 'new_bytes': len(data)}
        if p.exists():
            w = p.read_bytes()
            r['worktree_identical'] = w == data
            r['worktree_identical_after_crlf_to_lf'] = w.replace(b'\r\n', b'\n') == data
        try:
            blob = git('show', f'HEAD:{rel(p)}')
            r['git_head_identical'] = blob == data
        except subprocess.CalledProcessError:
            r['git_head_identical'] = None  # not tracked
        ok &= bool(r.get('worktree_identical') or r.get('git_head_identical'))
        res[rel(p)] = r
    return res, ok


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split('\n\n')[0],
                                 epilog='See the module docstring for the config keys.')
    ap.add_argument('config', help='kernel config JSON (usually experiments/exp-NNN/kernel_config.json)')
    ap.add_argument('--out-dir', help='write into this directory instead of the configured paths')
    ap.add_argument('--check', action='store_true', help='compare with the existing files, write nothing')
    a = ap.parse_args(argv)
    sys.stdout.reconfigure(encoding='utf-8')
    cfg = json.loads(rpath(a.config).read_text(encoding='utf-8'))
    bad = [k for k in cfg if k not in ('template', 'script', 'substitutions', 'metadata', 'metadata_path',
                                       'metadata_indent') and not k.startswith('_')]
    if bad:
        raise ValueError(f'unknown config keys (prefix "_" for comments): {bad}')
    files, report = build(cfg)
    if a.check:
        res, ok = check(files)
        print(json.dumps({'files': res, **report}, indent=1))
        return 0 if ok else 1
    written = {}
    for p, data in files.items():
        q = Path(a.out_dir) / p.name if a.out_dir else p
        q.parent.mkdir(parents=True, exist_ok=True)
        q.write_bytes(data)
        written[str(q)] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
    print(json.dumps({'wrote': written, **report}, indent=1))
    return 0


if __name__ == '__main__':
    sys.exit(main())
